params.python_function:
comments = {{ vars.steps.List_Exceptions.data | map(attribute='comment') | list | tojson }}
ids = {{ vars.steps.List_Exceptions.data | map(attribute='exceptionId') | list | tojson }}
now_epoch = {{ vars.now_epoch | int }}
marker = {{ vars.marker | tojson }}
expired_ids = []
managed_fresh = 0
unmanaged = 0
i = 0
while i < len(comments):
    c = comments[i]
    parsed = ''
    handled = False
    if c and marker in c:
        rest = c[c.index(marker) + len(marker):]
        for ch in rest:
            if ch.isdigit():
                parsed = parsed + ch
            else:
                break
        if parsed == '' or int(parsed) >= now_epoch:
            managed_fresh = managed_fresh + 1
        else:
            expired_ids.append(str(ids[i]))
        handled = True
    if not handled:
        unmanaged = unmanaged + 1
    i = i + 1
print({'expiredIdsCsv': ','.join(expired_ids),
       'expiredCount': len(expired_ids),
       'managedFreshCount': managed_fresh,
       'unmanagedCount': unmanaged})

names = {{ vars.steps.Get_Fleet.data | map(attribute='name') | list | tojson }}
versions = {{ vars.steps.Get_Fleet.data | map(attribute='version') | list | tojson }}
states = {{ vars.steps.Get_Fleet.data | map(attribute='state') | list | tojson }}
states_adtl = {{ vars.steps.Get_Fleet.data | map(attribute='stateAdditionalInfo') | list | tojson }}
os_families = {{ vars.steps.Get_Fleet.data | map(attribute='osFamily') | list | tojson }}
last_seens = {{ vars.steps.Get_Fleet.data | map(attribute='lastSeenTime') | list | tojson }}
inst_os = {{ vars.steps.Get_Installers.data.availableCollectorInstallers | map(attribute='osFamily') | list | tojson }}
inst_ver = {{ vars.steps.Get_Installers.data.availableCollectorInstallers | map(attribute='version') | list | tojson }}
latest = {}
j = 0
while j < len(inst_os):
    fam = inst_os[j]
    if fam in latest:
        if inst_ver[j] > latest[fam]:
            latest[fam] = inst_ver[j]
    else:
        latest[fam] = inst_ver[j]
    j = j + 1
rows = []
healthy = 0
outdated = 0
offline = 0
i = 0
while i < len(names):
    fam = os_families[i]
    ver = str(versions[i])
    state = str(states[i])
    flag = 'ok'
    if state != 'Running':
        flag = 'state:' + state
        offline = offline + 1
    else:
        if fam in latest and ver != str(latest[fam]):
            flag = 'outdated (available ' + str(latest[fam]) + ')'
            outdated = outdated + 1
        else:
            healthy = healthy + 1
    rows.append((flag, str(names[i]), ver, state,
                 str(states_adtl[i]), str(last_seens[i])))
    i = i + 1
html = '<table class="table" border="1" style="border-collapse:collapse;">'
html = html + '<tr><th style="text-align:left;padding:4px 10px;">Collector</th>'
html = html + '<th style="text-align:left;padding:4px 10px;">Version</th>'
html = html + '<th style="text-align:left;padding:4px 10px;">State</th>'
html = html + '<th style="text-align:left;padding:4px 10px;">Last seen</th></tr>'
i = 0
while i < len(rows):
    r = rows[i]
    tone = ' style="padding:4px 10px;"'
    if not r[0].startswith('ok'):
        tone = ' style="padding:4px 10px;background:rgba(247,107,21,.12);"'
    html = html + '<tr><td' + tone + '>' + r[1] + '</td><td' + tone + '>' + r[2] + '</td><td' + tone + '>' + r[3] + '</td><td' + tone + '>' + r[5] + '</td></tr>'
    i = i + 1
html = html + '</table>'
print({'fleet_html': html, 'fleet_size': len(names), 'healthy': healthy,
       'outdated': outdated, 'not_running': offline,
       'latest_windows': (latest['Windows'] if 'Windows' in latest else '')})
